function chart(ctx,node,name,title,source,rows){const wrapper=node.tagName?.toLowerCase()==='svg'?wideChart(node):node,graphic=wrapper.querySelector('svg'),result=figure(graphic,{name:'dataeconomy-'+name,title:'Экономика данных и цифровая трансформация государства · '+title,source,rows:arr(rows).map(r=>({...r,Название_визуализации:title,Источник_визуализации:source}))});graphic.replaceWith(wrapper);wrapper.append(graphic);return result;}

const clip=(s,n=38)=>String(s||'').length>n?String(s).slice(0,n-1)+'…':String(s||'');
function sourceText(ctx,s){if(s.has_confirmed_source===false)return 'Реестровая позиция '+s.registry_code+'. '+s.title+'. Подтверждённый числовой источник ЕМИСС не установлен.';const acquired=/acquisition|snapshot/.test(s.published_at_semantics||'');return 'ЕМИСС '+sid(s)+'. '+s.title+'. '+sourceUnit(s)+'. '+(acquired?'Дата получения сохранённого среза: ':'Дата публикации: ')+date(s.published_at||s.last_success||statistics(ctx).statistical_as_of)+'. '+(s.origin_kind==='secondary_emiss_republication'?'Получено из вторичной републикации ЕМИСС.':'');}
function sourceFoot(ctx,s){if(s.has_confirmed_source===false)return h('div',{class:'source-foot'},h('span',{},sourceText(ctx,s)),s.catalog_url?link('Раздел каталога ЕМИСС',s.catalog_url):null);return h('div',{class:'source-foot'},h('span',{},sourceText(ctx,s)),link('Карточка ЕМИСС',sourceURL(s)),s.republisher_url?link('Републикация и исходный файл',s.republisher_url):null);}
function sourceSelect(ctx,pool=sources(ctx),fallback){const s=pool.find(s=>s.registry_code&&s.registry_code===ctx.state.indicator)||pool.find(s=>sid(s)===ctx.state.source)||pool.find(s=>sid(s)===fallback)||pool[0];return{s,control:select('Показатель',pool.map(s=>[sid(s),sourceName(s)]),sid(s),v=>ctx.set({source:v,indicator:null,year:null,frequency:null,period:null,category:null,q:null,r:null,compare:null,fd:null,geography:null,goal:null,goalYear:null,baseYear:null,otherSource:null,otherPeriod:null}))};}
function sourceNotes(s){return h('div',{},s.source_status==='discontinued'?note('Исполнение показателя прекращено. Опубликованные наблюдения сохранены для проверки источника. Оценка текущего выполнения цели и сценарная траектория по нему не строятся.','warning'):null,s.source_status==='methodology_review_required'?note('Редакции методики требуют согласования. Наблюдения показываются раздельно. Однородный временной тренд, выполнение цели и прогноз по ним не определяются.','warning'):null,s.period_note?note(s.period_note):null,s.unit_conflict||arr(s.quality_flags).some(x=>String(x?.code||x).includes('unit_conflict'))?note('В опубликованной единице и содержательном определении есть противоречие. Исходная единица сохранена. Процент выполнения плана не рассчитывается.','warning'):null,s.target_comparison_allowed===false||s.temporal_comparison_eligible===false?note(s.target_comparison_note||s.comparison_note||'Сопоставление с планом требует дополнительной проверки методики, единицы или временного окна.','warning'):null,s.note&&s.note!==s.period_note?para(s.note,'small muted'):null,s.geography_note?para(s.geography_note,'small muted'):null);}

function frequencyName(frequency,source={},row={}){const semantics=row.period_semantics||source.period_semantics||'';if(frequency==='quarterly'&&semantics==='cumulative_ytd_quarterly')return 'Нарастающий итог на конец квартала';if(!['annual','yearly'].includes(frequency)&&semantics==='annual_estimate_republished_monthly')return 'Месячная публикация годового показателя';if(!['annual','yearly'].includes(frequency)&&semantics.startsWith('cumulative_since_'))return 'Накопление программы с '+(source.cumulative_since||semantics.replace('cumulative_since_',''))+' года';if(!['annual','yearly'].includes(frequency)&&semantics==='cumulative_program_baseline_unverified')return 'Накопленный срез программы. База требует проверки';return FREQ[frequency]||frequency;}
function frequencyControls(ctx,rows){const fs=[...new Set(rows.map(r=>r.frequency))].filter(Boolean),years=[...new Set(rows.map(r=>String(r.year||r.period_end||r.period).slice(0,4)))].filter(x=>/^\d{4}$/.test(x)).sort().reverse();return [select('Периодичность',[['','Все типы'],...fs.map(f=>[f,frequencyName(f,{},rows.find(r=>r.frequency===f))])],ctx.state.frequency||'',v=>ctx.set({frequency:v||null})),select('Год',[['','Все годы'],...years.map(y=>[y,y])],ctx.state.year||'',v=>ctx.set({year:v||null}))];}
const filteredRows=(ctx,rows)=>rows.filter(r=>(!ctx.state.frequency||r.frequency===ctx.state.frequency)&&(!ctx.state.year||String(r.year||r.period_end||r.period).startsWith(ctx.state.year)));

