 if(!selected)append(root,note('Сопоставимая годовая база для выбранного источника не установлена. Поле исходного значения остаётся пустым до ввода пользователя. Последний месяц не подставляется как годовой результат.'));
 if(unitBlocked)append(root,note('Перенос паспортной цели в шкалу источника не подтверждён. Автоматическое заполнение цели отключено. Ввод пользователя описывает условную задачу и не устраняет неопределённость исходной единицы.','warning'));
