 const result=buildPlanScenario(fact,goal,baseYear,goalYear,mode,domain);
 if(result){const rows=result.rows.map((r,i)=>({...r,role:i===0?(manual?'Исходное предположение':'Декабрьская запись, условная база'):r.role,unit:sourceUnit(s),source:sourceURL(s),baseline_kind:manual?'user_assumption':'conditional_december_equivalent',assumption:mode==='linear'?'Равное абсолютное изменение':'Равный относительный темп'}));append(root,stats([['Среднее абсолютное изменение',fmt(result.annualChange,4),differenceUnit(s)+' в год'],['Необходимый сложный темп',fmt(result.annualRate,4)+' %','при положительной базе и цели']]),panel('Условный путь к цели',sourceUnit(s),chart(ctx,lineChart([{name:'Условная траектория',color:C[0],dash:'6 4',points:rows.map(r=>({x:Date.UTC(r.year,11,31),y:r.value,label:String(r.year)}))}],{height:350,unit:sourceUnit(s),label:'Условный путь к цифровому результату'}),'scenario','Условный путь к цели',sourceText(ctx,s)+' Параметры задаются пользователем либо берутся из условной декабрьской базы и датированного паспорта. Вероятность достижения не определяется.',rows)),table(rows,[{key:'year',label:'Год',numeric:true,render:v=>String(v)},{key:'value',label:'Значение',numeric:true,decimals:5},{key:'unit',label:'Единица'},{key:'role',label:'Статус'},{key:'assumption',label:'Предположение'}],{filename:'dataeconomy-scenario.csv',pageSize:12}));}
 else append(root,note('Для расчёта нужны конечные неотрицательные значения, целые годы и положительный горизонт до 30 лет. Сложный темп требует положительных базы и цели. Ограничение 0–100 применяется к долям, индексы с фиксированной базой могут превышать 100.'));
